export function compareMarket(research,quotes){
 const symbols=[...new Map(research.filter(r=>['universe','candidate'].includes(r.kind)||(r.kind==='signal'&&r.verified&&!/tecnico sperimentale|M1D-v0|esperimento meccanico/i.test(r.summary||''))).map(r=>[r.symbol,r])).values()];
 const out=symbols.map(r=>{const map=new Map();for(const q of quotes.filter(q=>q.symbol===r.symbol).sort((a,b)=>a.recorded_at.localeCompare(b.recorded_at)))map.set(q.trade_date,q);const qs=[...map.values()].sort((a,b)=>a.trade_date.localeCompare(b.trade_date));const last=qs.at(-1),prev=qs.at(-2),base=map.get('2026-11-09');
 const host=q=>{try{return new URL(q?.source).hostname}catch{return ''}};const same=last&&prev&&last.currency===prev.currency&&host(last)===host(prev);return {symbol:r.symbol,sector:r.sector,last:last||null,previous:prev||null,baseline:base||null,session_return:same?(last.close/prev.close-1)*100:null,since_start:last&&base&&last.currency===base.currency&&host(last)===host(base)?(last.close/base.close-1)*100:null,status:last?'Dati disponibili':'Fonte non disponibile'};});
 for(const r of out){if(r.session_return===null)continue;const peers=out.filter(p=>p.sector===r.sector&&p.session_return!==null&&p.last.trade_date===r.last.trade_date&&p.previous.trade_date===r.previous.trade_date&&p.last.currency===r.last.currency);const best=peers.sort((a,b)=>b.session_return-a.session_return)[0];r.peer_count=peers.length;r.best_peer=best.symbol;r.best_return=best.session_return;r.gap_pp=r.session_return-best.session_return;const tracked=peers.filter(p=>p.since_start!==null&&p.baseline?.trade_date===r.baseline?.trade_date).sort((a,b)=>b.since_start-a.since_start);if(tracked.length&&r.since_start!==null){r.best_since_peer=tracked[0].symbol;r.best_since_return=tracked[0].since_start;r.gap_since_pp=r.since_start-tracked[0].since_start;}}
 return out;
}
