export function allocateCapital(items,amount,risk){const rule=riskRules[risk];if(!Object.hasOwn(riskRules,risk))throw Error('Profilo non valido');const out=[...new Map(items.map(x=>[x.symbol,x])).values()].slice(0,15).map(x=>({...x,allocated:0}));let left=amount*rule.exposure;const sectors={};for(let round=0;round<40&&left>.01;round++){const eligible=out.filter(x=>x.allocated<amount*rule.maxName-.01&&(sectors[x.sector]||0)<amount*rule.maxSector-.01);if(!eligible.length)break;const sum=eligible.reduce((a,x)=>a+x.score,0);let added=0;for(const x of eligible){const n=Math.max(0,Math.min(left*x.score/sum,amount*rule.maxName-x.allocated,amount*rule.maxSector-(sectors[x.sector]||0)));x.allocated+=n;sectors[x.sector]=(sectors[x.sector]||0)+n;added+=n}left-=added;if(added<.01)break}return {positions:out.filter(x=>x.allocated>.01),cash:amount-out.reduce((a,x)=>a+x.allocated,0),version:'paper-allocation-v1',rule};}
