async function simPortfolioValue(p,market){let invested=0;let asof=null;const items=[];for(const holding of p.positions){const m=market.find(x=>x.symbol===holding.symbol);const last=m?.last;if(!last){items.push({...holding,value:null});continue}asof=!asof||last.trade_date<asof?last.trade_date:asof;items.push({...holding,last,last_usd_value:holding.quantity*last.close});}const fx=asof&&(p.currency==='EUR'||items.some(h=>h.currency==='EUR'))?await fxFor(asof):{rate:1,date:asof,source:null};for(const h of items){h.value=h.last_usd_value==null?null:h.last_usd_value*(h.currency==='EUR'?fx.rate:1)/(p.currency==='EUR'?fx.rate:1);if(h.value!==null)invested+=h.value}const complete=items.every(h=>h.value!==null)&&new Set(items.filter(h=>h.last).map(h=>h.last.trade_date)).size<=1;const total=complete?p.cash+invested:null;return {...p,positions:items,value:total,gain:total===null?null:total-p.amount,return_pct:total===null?null:(total/p.amount-1)*100,as_of:asof,current_fx:fx,complete}}
