async function seedSemanticSamples(req,env){const p=await smEnsure(env);if(!p.integrity)return {state:'protocol_review',created:0};const {eligible}=await simEligible(env,'semantic');if(!eligible.length)return {state:'waiting_for_economic_candidates',created:0};const principal='study:'+p.version,created=[];for(const risk of ['low','medium','high']){if(await env.DB.prepare("SELECT id FROM simulation_portfolios WHERE principal=? AND json_extract(payload,'$.risk')=?").bind(principal,risk).first())continue;const origin=new URL(req.url).origin,headers=new Headers(req.headers);headers.set('Origin',origin);headers.set('Content-Type','application/json');const response=await simulatorEndpoint(new Request(origin+'/api/simulator',{method:'POST',headers,body:JSON.stringify({operation:'portfolio',name:'Campione economico v2 · '+risk,amount:10000,currency:'EUR',risk,allocation_engine:'semantic'})}),env,principal);if(!response.ok)throw Error('Campione semantico non creato');created.push((await response.json()).id)}return {state:'ready',created:created.length,ids:created}}
async function seedStudySamples(req,env){const protocol=await exEnsure(env);const signals=await pdInvestmentSignals(env,'reference-v1');if(!signals.length)return {state:'waiting_for_signals',created:0};const principal='study:'+protocol.version,created=[];for(const risk of ['low','medium','high']){const existing=await env.DB.prepare("SELECT id FROM simulation_portfolios WHERE principal=? AND json_extract(payload,'$.risk')=?").bind(principal,risk).first();if(existing)continue;const origin=new URL(req?.url||'https://stokiq.online/').origin,headers=new Headers(req?.headers||{});headers.set('Origin',origin);headers.set('Content-Type','application/json');const request=new Request(origin+'/api/simulator',{method:'POST',headers,body:JSON.stringify({operation:'portfolio',name:'Campione studio v1 · '+({low:'basso',medium:'medio',high:'alto'}[risk]),amount:10000,currency:'EUR',risk,allocation_engine:'reference'})});const result=await simulatorEndpoint(request,env,principal);if(!result.ok)throw Error('Creazione campione non eseguita');const p=await result.json();created.push({id:p.id,risk})}return {state:'ready',created:created.length,portfolios:created,note:'Tre campioni virtuali di EUR 10.000, senza dati cliente; visibili nel Laboratorio.'};}
async function publishExperiment(snapshots,req,env,now){
 if(snapshots.length<1||snapshots.length>50)throw Error('Lotto da 1 a 50 titoli');
 const research=await call('list_research',{},req,env),existing=await registry(env);const deadline=new Date(Date.parse(now)+30*86400000);deadline.setUTCHours(21,0,0,0);const statements=[],published=[],skipped=[];
 const definition='Esperimento preregistrato M1D-v0: usare le ultime due chiusure Nasdaq disponibili al momento della pubblicazione; se la variazione è positiva prevedere prezzo alla scadenza >= prezzo iniziale x 1.05; se negativa prevedere prezzo <= prezzo iniziale x 0.95; variazione zero esclusa. Scadenza a 30 giorni di calendario, ore 21 UTC. Regola non calibrata; esito alla prima chiusura disponibile alla scadenza o successiva. Nessuna selezione del miglior orizzonte a posteriori.';
 for(const snap of snapshots){const symbol=text(snap.symbol,'simbolo',1,30);const r=research.find(x=>x.symbol===symbol&&['universe','candidate'].includes(x.kind));if(!r)throw Error('Titolo non registrato: '+symbol);if(existing.some(x=>x.symbol===symbol&&x.pattern_name==='Esperimento momentum 1 seduta'&&x.pattern_version==='v0')){skipped.push({symbol,reason:'Esperimento già pubblicato'});continue}
 const baseline=positive(snap.close,'chiusura'),previous=positive(snap.previous_close,'chiusura precedente');if(!/^\d{4}-\d{2}-\d{2}$/.test(snap.trade_date)||!/^\d{4}-\d{2}-\d{2}$/.test(snap.previous_date)||snap.previous_date>=snap.trade_date)throw Error('Date di mercato non valide');const source=urls([snap.source])[0];if(new URL(source).hostname!=='api.nasdaq.com'||!source.includes('/quote/'+symbol+'/historical'))throw Error('Fonte Nasdaq incoerente');
 const change=(baseline/previous-1)*100;if(change===0){skipped.push({symbol,reason:'Variazione nulla'});continue}const direction=change>0?'up':'down',id=crypto.randomUUID(),sid=crypto.randomUUID(),cid=crypto.randomUUID();const sign=change>0?'positiva':'negativa';
 const p=validatePrediction({symbol,company:r.summary.split(' — ')[0],exchange:'Quotazione USA (fonte Nasdaq)',currency:'USD',sector:r.sector,direction,baseline,baseline_at:snap.trade_date+'T21:00:00Z',baseline_source:source,target:Number((baseline*(direction==='up'?1.05:.95)).toPrecision(10)),deadline:deadline.toISOString(),benchmark:'Comparabili osservati di categoria (confronto descrittivo)',pattern_name:'Esperimento momentum 1 seduta',pattern_version:'v0',pattern_definition:definition,thesis:'Previsione sperimentale meccanica, non calibrata: la variazione di prezzo osservata fra '+snap.previous_date+' e '+snap.trade_date+' è '+sign+' ('+change.toFixed(2)+'%). Si testa se questa direzione prosegue fino all’obiettivo prestabilito del 5% a 30 giorni. La pubblicazione è prospettica; il dato precedente è solo una variabile osservata.',catalyst:'Segnale tecnico di prezzo verificato sulla serie Nasdaq; nessun catalizzatore brevettuale o fondamentale è presunto da questa regola.',risks:'Campione di una seduta, regola non validata, correlazione settoriale, inversioni, notizie future e operazioni societarie. La probabilità iniziale è un prior neutrale, non una stima predittiva affidabile.',invalidation:'La tesi risulta non confermata se alla scadenza il prezzo non raggiunge l’obiettivo nella direzione dichiarata; note e rettifiche non cambiano i criteri originali.',sources:[source,...r.sources]},now);
 p.prior_probability=.5;p.prior_sample=0;p.origin_signal_id=sid;p.origin_candidate_id=cid;p.experimental=true;
 const signal={kind:'signal',symbol,sector:r.sector,verified:true,sources:[source],summary:'Segnale tecnico sperimentale: due chiusure Nasdaq '+previous+' e '+baseline+' USD, rispettivamente '+snap.previous_date+' e '+snap.trade_date+'. Variazione '+change.toFixed(2)+'%. Non è una notizia fondamentale o una scoperta brevettuale.'};
 const candidate={kind:'candidate',symbol,sector:r.sector,verified:false,sources:[source],origin_signal_id:sid,summary:'Candidato esclusivamente per l’esperimento meccanico M1D-v0, richiesto dall’autore. Fonte: variazione delle ultime due chiusure Nasdaq. Regola non calibrata; nessuna validazione fondamentale o brevettuale implicita.'};
 const dg=await digest(JSON.stringify({id,published_at:now,...p}));
 statements.push(env.DB.prepare('INSERT INTO research (id,created_at,payload) VALUES (?,?,?)').bind(sid,now,JSON.stringify(signal)),env.DB.prepare('INSERT INTO research (id,created_at,payload) VALUES (?,?,?)').bind(cid,now,JSON.stringify(candidate)),env.DB.prepare('INSERT INTO predictions (id,published_at,payload,digest) VALUES (?,?,?,?)').bind(id,now,JSON.stringify(p),dg));
 for(const [day,close] of [[snap.previous_date,previous],[snap.trade_date,baseline]])statements.push(env.DB.prepare('INSERT OR IGNORE INTO market_closes (id,symbol,trade_date,close,currency,source,recorded_at) VALUES (?,?,?,?,?,?,?)').bind(crypto.randomUUID(),symbol,day,close,'USD',source,now));
 published.push({id,symbol,direction,baseline,target:p.target,deadline:p.deadline});}
 for(let i=0;i<statements.length;i+=20)await env.DB.batch(statements.slice(i,i+20));
 return {published_at:now,experiment:'M1D-v0 — regola meccanica non calibrata',published,skipped};
}
