const studyDate=v=>v?new Date(v).toLocaleString('it-IT',{timeZone:'Asia/Dubai',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})+' Dubai':'—';
async function studyLoad(){try{const r=await fetch('/api/experiment'),d=await r.json();if(!r.ok)throw Error(d.error);const me=await fetch('/api/me').then(x=>x.json()),p=d.protocol;$('study-protocol').innerHTML=p?'<p><strong>'+esc(p.id)+'</strong> · '+(p.integrity?'integrità verificata':'verifica integrità richiesta')+' · riferimento '+esc(p.reference)+'</p><p>Avvio: '+studyDate(p.created_at)+'<br>Prima revisione del campione: '+studyDate(p.initial_review_at)+'<br>Esiti: 30 giorni dopo ciascun ingresso. La raccolta continua oltre la revisione dei 15 giorni con le stesse regole, per consentire la valutazione futura dei modelli adattivi.</p><p class="small">Regole e pesi del riferimento sono immutabili. Le nuove versioni adattive restano concorrenti separati; dati anteriori allo studio non diventano risultati del nuovo protocollo.</p><p class="hash">Regole SHA-256: '+esc(p.rules_hash)+'</p>':'Il primo ciclo operativo registra il protocollo immutabile.';const critical=d.alerts.filter(a=>a.severity==='critical').length;$('study-alert-summary').textContent=d.alerts.length?d.alerts.length+' verifiche operative aperte, di cui '+critical+' critiche.':'Nessun allarme operativo aperto.';const report=d.reports[0];$('study-report').innerHTML=report?'<h4>Riepilogo '+esc(report.day)+' · Dubai</h4><p class="small">Eventi '+report.counts.events+' · previsioni registro '+report.counts.predictions+' · previsioni dei modelli '+report.counts.model_forecasts+' · esiti '+report.counts.outcomes+' · portafogli '+report.counts.portfolios+'. Aggiornato '+studyDate(report.generated_at)+'.</p>':'<p class="small">Nessun riepilogo ancora registrato.</p>';$('study-samples').innerHTML=(d.samples||[]).map(s=>'<article class="research-card"><h3>'+esc({low:'Basso',medium:'Medio',high:'Alto'}[s.risk])+'</h3><p>'+esc(s.state==='waiting_entry'?'In attesa della prima chiusura futura':s.state==='settled'?'Orizzonte concluso':s.state==='review_required'?'Dati da verificare':'Ingresso registrato')+'</p><p class="small">Piano '+number(s.planned_exposure_pct)+'% · '+esc(s.symbols.join(', '))+'</p><p>Valore '+number(s.value)+' '+esc(s.currency)+' · netto '+number(s.return_pct)+'%</p><p class="small">Equiponderato '+number(s.benchmarks?.equal_weight?.return_pct)+'% · mercato '+number(s.benchmarks?.market?.return_pct)+'% · dati '+esc(s.as_of||'ingresso non ancora avvenuto')+'</p></article>').join('')||'<p class="small">Il prossimo ciclo crea i tre campioni quando sono disponibili segnali del riferimento con prezzi verificati.</p>';$('study-admin').classList.toggle('hidden',!(me.owner||me.view_admin));$('study-run').classList.toggle('hidden',!me.owner);$('study-action-form').closest('details').classList.toggle('hidden',!me.owner);$('study-backup').classList.toggle('hidden',!me.root);$('study-alerts').innerHTML=(d.alerts||[]).map(a=>'<p class="small"><strong>'+esc(a.severity)+'</strong> · '+esc(a.message||a.id)+' · '+studyDate(a.updated_at)+'</p>').join('');$('study-backups').innerHTML=(d.backups||[]).map(b=>'<div class="timeline-item"><strong>'+esc(b.status)+'</strong> · '+studyDate(b.created_at)+'<p class="small">'+(b.status==='verified'?esc(b.tables+' tabelle / '+b.rows+' righe · integrità e rilettura verificate'):esc(b.error||'Backup in esecuzione'))+'</p>'+(me.root&&b.status==='verified'?'<a href="/api/experiment/backup/download?id='+encodeURIComponent(b.id)+'">Scarica archivio cifrato ↓</a>':'')+'</div>').join('')||'<p class="small">Backup verificato non ancora disponibile.</p>';}catch(e){$('study-alert-summary').textContent='Stato studio non disponibile: '+e.message}}
async function studyPost(url,body={}){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw Error(d.error||'Operazione non riuscita');await studyLoad();return d}
$('study-refresh').onclick=studyLoad;$('study-run').onclick=async()=>{const b=$('study-run');b.disabled=true;$('study-result').textContent='Verifica dati e archivio in corso…';try{const d=await studyPost('/api/experiment/run');$('study-result').textContent=d.busy?'Un controllo è già in corso.':'Controlli registrati. Backup: '+(d.backup?.status||'già aggiornato nel giorno corrente')+'.';await simLoad()}catch(e){$('study-result').textContent=e.message}finally{b.disabled=false}};$('study-backup').onclick=async()=>{const b=$('study-backup');b.disabled=true;$('study-result').textContent='Cifratura, archiviazione e rilettura del backup…';try{const d=await studyPost('/api/experiment/backup');$('study-result').textContent='Backup '+d.status+' · '+d.rows+' righe verificate.'}catch(e){$('study-result').textContent=e.message}finally{b.disabled=false}};$('study-action-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const a=Object.fromEntries(new FormData(f));a.symbol=a.symbol.trim().toUpperCase();await studyPost('/api/experiment/actions',a);$('study-action-result').textContent='Evento documentato registrato. Le valorizzazioni successive ne terranno conto.';f.reset();await simLoad()}catch(e){$('study-action-result').textContent=e.message}finally{b.disabled=false}};

const graphLabels={mentions:'Menzione nel documento',source_issuer:'Emittente del documento',describes_patent:'Pubblicazione brevettuale',collaboration_announcement:'Collaborazione dichiarata',commercial_relationship:'Relazione commerciale dichiarata',acquisition_announcement:'Acquisizione annunciata'};
function graphEvidenceHtml(d){const names=new Map((d.nodes||[]).map(n=>[n.id,n.symbol||n.label]));const relations=(d.edges||[]).filter(e=>['collaboration_announcement','commercial_relationship','acquisition_announcement'].includes(e.relation));return relations.length?relations.map(e=>'<article class="research-card"><span class="tag">Da approfondire · fonte singola</span><p class="graph-evidence-title">'+esc(names.get(e.source_id)||e.source_id)+' ↔ '+esc(names.get(e.target_id)||e.target_id)+'</p><p>'+esc(graphLabels[e.relation]||e.relation)+'</p><blockquote class="graph-quote">'+esc(e.payload.quote)+'</blockquote><p class="small">Documento: '+esc(e.title)+'<br>Pubblicazione '+(e.published_at?fmt(e.published_at):'data non verificata')+' · Acquisito '+fmt(e.acquired_at)+'</p>'+link(e.url)+'<p class="small">Dichiarazione presente nella fonte; direzione economica e impatto sul titolo non dedotti.</p></article>').join(''):'<p class="small">Non ci sono ancora relazioni esplicite estratte in questa vista. I documenti e le semplici menzioni restano consultabili nella rete.</p>'}
async function graphLoad(symbol=''){try{const r=await fetch('/api/graph'+(symbol?'?symbol='+encodeURIComponent(symbol):''));const d=await r.json();if(!r.ok)throw Error(d.error||'Rete non disponibile');const relations=d.edges.filter(e=>['collaboration_announcement','commercial_relationship','acquisition_announcement'].includes(e.relation));$('graph-status').textContent=d.documents+' documenti · '+d.document_versions+' versioni acquisite · '+relations.length+' relazioni nella vista · '+d.jobs.map(j=>j.n+' '+({pending:'in attesa',completed:'completati',retry:'da ritentare',failed:'non acquisiti'}[j.state]||j.state)).join(' · ')+(d.truncated?' · Vista limitata agli ultimi '+d.limit+' collegamenti':'');$('graph-evidence').innerHTML=graphEvidenceHtml(d);$('graph-hypotheses').innerHTML=d.hypotheses.length?d.hypotheses.map(h=>'<article class="research-card"><span class="tag">Ipotesi · da verificare</span><h3>'+esc(h.symbol)+' · evento su '+esc(h.payload.trigger_issuer)+'</h3><p class="small">Formulata '+fmt(h.created_at)+' · '+esc(h.rule_version)+'</p><p>Relazione precedente, nota dal '+fmt(h.payload.prior.known_at)+'</p><blockquote class="graph-quote">'+esc(h.payload.prior.quote)+'</blockquote>'+link(h.payload.prior.url)+'<p>Nuovo evento</p><blockquote class="graph-quote">'+esc(h.payload.trigger_document.quote)+'</blockquote>'+link(h.payload.trigger_document.url)+'<ul>'+h.payload.required_checks.map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul><p class="small">Nessuna previsione o rendimento dedotto automaticamente.</p></article>').join(''):'<p class="small">Nessuna ipotesi temporale attivata. La memoria si sta costruendo; servono relazioni documentate e successivi eventi nuovi.</p>';const nodes=d.nodes.slice(0,18),ids=new Set(nodes.map(n=>n.id)),positions=new Map(nodes.map((n,i)=>[n.id,{x:380+260*Math.cos(i*2*Math.PI/nodes.length),y:180+130*Math.sin(i*2*Math.PI/nodes.length)}]));let svg='<svg viewBox="0 0 760 360" role="img" aria-label="Rete di aziende e documenti: verde aziende, blu documenti">';for(const e of d.edges.filter(e=>ids.has(e.source_id)&&ids.has(e.target_id))){const a=positions.get(e.source_id),b=positions.get(e.target_id);svg+='<line x1="'+a.x+'" y1="'+a.y+'" x2="'+b.x+'" y2="'+b.y+'" stroke="'+(['mentions','source_issuer'].includes(e.relation)?'#b6cbd2':'#087f70')+'" stroke-width="'+(['mentions','source_issuer'].includes(e.relation)?1:3)+'"><title>'+esc(graphLabels[e.relation]||e.relation)+'</title></line>'}for(const n of nodes){const p=positions.get(n.id);svg+='<g class="graph-node" '+(n.symbol?'data-graph-symbol="'+esc(n.symbol)+'" role="button" tabindex="0" aria-label="Esplora '+esc(n.symbol)+'"':'')+'><title>'+esc(n.label)+'</title><circle cx="'+p.x+'" cy="'+p.y+'" r="'+(n.symbol?22:10)+'" fill="'+(n.symbol?'#087f70':'#466c94')+'"/><text text-anchor="middle" x="'+p.x+'" y="'+(p.y+36)+'">'+esc(n.symbol||(n.kind==='patent'?n.label:'Documento'))+'</text></g>'}svg+='</svg>';$('graph-map').innerHTML=nodes.length?svg:'<p style="padding:18px">La rete si popola con l’acquisizione dei documenti. Nessun collegamento inventato o ricostruito retroattivamente.</p>';$('graph-errors').innerHTML='<p>'+esc(d.note)+'</p><h4>Ultime acquisizioni</h4>'+d.recent_documents.map(v=>'<p>'+link(v.url)+' · '+esc(v.extraction_basis==='event_metadata'?'Solo metadati della fonte':'Testo acquisito · estrazione limitata')+' · '+fmt(v.acquired_at)+'</p>').join('')+'<h4>Acquisizioni da verificare</h4>'+d.errors.map(e=>'<p>'+link(e.url)+' · '+esc(e.state)+' · '+e.attempts+' tentativi · '+esc(e.error||'')+'</p>').join('');}catch(e){$('graph-status').textContent=e.message}}
$('graph-filter').onsubmit=e=>{e.preventDefault();const symbol=$('graph-symbol').value.trim().toUpperCase();if(symbol&&!/^[A-Z0-9.\-]{1,30}$/.test(symbol)){$('graph-status').textContent='Simbolo non valido';return}graphLoad(symbol)};$('graph-reset').onclick=()=>{$('graph-symbol').value='';graphLoad()};function graphSelect(e){const n=e.target.closest('[data-graph-symbol]');if(!n)return;$('graph-symbol').value=n.dataset.graphSymbol;graphLoad(n.dataset.graphSymbol)};$('graph-map').onclick=graphSelect;$('graph-map').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();graphSelect(e)}};

fetch('/api/retrospective').then(r=>r.json()).then(d=>{if(!d.active){$('retro-status').textContent='La raccolta si inizializza al prossimo ciclo.';return}let html='<p>'+esc(d.protocol.start)+' → '+esc(d.protocol.end)+' · '+esc(d.states.map(s=>s.n+' '+s.state).join(' · '))+'</p>';if(d.report){const v=d.report,better=v.candidate.brier<v.reference.brier;html+='<p><strong>'+(better?'Differenza esplorativa favorevole al candidato; non è una validazione.':'Il candidato storico non migliora il riferimento nel periodo di verifica.')+'</strong> Modello in quarantena; nessuna modifica al test attuale.</p><p>'+v.training_n+' esempi di apprendimento · '+v.evaluation_n+' di verifica · '+v.embargo_excluded+' esclusi per separare i periodi.</p><div style="overflow:auto"><table><thead><tr><th>Modello</th><th>Brier · minore è meglio</th><th>Direzioni corrette</th></tr></thead><tbody><tr><td>Riferimento congelato</td><td>'+number(v.reference.brier)+'</td><td>'+number(100*v.reference.accuracy)+'%</td></tr><tr><td>Candidato storico · quarantena</td><td>'+number(v.candidate.brier)+'</td><td>'+number(100*v.candidate.accuracy)+'%</td></tr></tbody></table></div><p class="small">Queste percentuali sono accuratezze direzionali sul campione storico, non rendimenti né probabilità di guadagno futuro. Il campione è scelto dall’universo attuale; gli esiti a 30 giorni si sovrappongono. Evidenze: date e metadati dei depositi SEC, non una ricostruzione causale completa di tutti i comunicati. Rendimenti di prezzo, copertura rettifiche parziale; costi e dividendi esclusi.</p><details><summary>Titoli e performance descrittiva del periodo</summary>'+v.cases.map(c=>'<p>'+esc(c.symbol)+' · '+number(c.period_return_pct)+'% · '+c.filings+' depositi SEC</p>').join('')+'</details><p><a href="/api/retrospective" download="stokiq-studio-storico.json">Esporta studio storico JSON</a></p>'}else html+='<p>Raccolta storica e confronto in corso. Nessun risultato di efficacia disponibile.</p>';$('retro-status').innerHTML=html}).catch(()=>{$('retro-status').textContent='Stato della ricerca retrospettiva non disponibile'});
