const KNOWLEDGE=[{"document": "Flusso di Lavoro Analisi Titoli", "page": 1, "text": "PROCES SO DI ANALISI DI MERCATO\n\n\n\n\nDall'analisi dei pattern al\nmonitoraggio continuo dei mercati\n\nPresentazione del processo proposto per individuare pattern comuni nelle performance azionarie\nstraordinarie, estenderli ad altri titoli e settori, e mantenere un monitoraggio continuo.\n\n\n\n\n 1", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Flusso di Lavoro Analisi Titoli", "page": 2, "text": "O BIE TT IVO\n\n\nDa osservazione isolata a processo ripetibile\n Capire\n 1\n Perché sono accadute le performance fuori scala\n\n Trasformare l'osservazione di alcuni casi\n Verificare\n di performance azionarie fuori scala in 2\n un processo ripetibile. Se lo schema si ripete su altri titoli\n\n\n Individuare\n 3\n I settori dove è più probabile che si ripeta\n\n\n Un metodo per capire perché certi movimenti accadono, e per Restare aggiornati\n restare pronti quando si ripetono. 4\n Nel tempo, senza ripartire da zero ogni volta\n\n\n\n\n 2", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Flusso di Lavoro Analisi Titoli", "page": 3, "text": "LE SEI FASI DEL FL USSO\n\n\nFase 1 — 3: dai casi al perimetro esteso\n\n\n\n 1 2 3\n\n\n Analisi dei casi Individuazione del pattern Estensione ad altri titoli\n\n\n Esaminare gli esempi di performance\n Confrontare le variabili emerse per isolare Applicare il pattern individuato ad altri titoli\n straordinarie forniti e scomporli nelle\n gli elementi ricorrenti comuni a tutti i casi, dei mercati americani ed europei, per\n variabili che le hanno determinate\n distinguendoli dagli aspetti specifici di ogni verificare se lo stesso schema è già\n (catalizzatore, settore, contesto di\n singolo titolo. riconoscibile altrove.\n mercato).\n\n\n\n\n 3", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Flusso di Lavoro Analisi Titoli", "page": 4, "text": "LE SEI FASI DEL FL USSO\n\n\nFase 4 — 6: settori e monitoraggio continuo\n\n\n\n 4 5 6\n\n\n Mappatura dei settori Monitoraggio continuo Osservazione dei prezzi\n\n\n Individuare i settori in maggiore sviluppo\n Seguire l'andamento di Borsa dei titoli\n (biomedicale, AI, infrastrutture Seguire in background gli sviluppi dei settori\n attenzionati per cogliere opportunità di\n informatiche, energia pulita) e i relativi e dei titoli individuati, con segnalazione\n correzione (ingresso) o di rialzo\n fattori chiave da tracciare (IPO, brevetti, tramite notifica delle notizie rilevanti.\n (uscita/conferma del trend).\n test, autorizzazioni).\n\n\n\n\n 4", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Flusso di Lavoro Analisi Titoli", "page": 5, "text": "COSA SERVE\n\n\nInput necessari per ogni fase\n\n Fasi 1-2 Elenco di titoli/eventi da analizzare come casi di partenza, anche non esaustivo.\n\n\n\n\n Perimetro di mercato su cui estendere la ricerca (es. mercati USA ed Europa, eventualmente filtrato per\n Fase 3\n capitalizzazione o settore).\n\n\n\n Elenco dei settori di interesse e, per ciascuno, le fonti primarie da tracciare (registri brevetti, autorità regolatorie,\n Fase 4\n calendari IPO, roadmap di prodotto).\n\n\n\n Watchlist di titoli/settori da tenere sotto osservazione e le soglie che devono far scattare una segnalazione\n Fasi 5-6\n (variazione di prezzo, volume, notizia).\n\n\n\n 5", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Flusso di Lavoro Analisi Titoli", "page": 6, "text": "RISULTATO\n\n\nOutput atteso\n\n\n 1 Pattern interpretativo comune 2 Lista di titoli candidati\n\n\n Sintetizzabile in poche variabili ricorrenti. USA ed Europa, che presentano lo stesso schema.\n\n\n\n\n 3 Mappa dei settori emergenti 4 Meccanismo di aggiornamento periodico\n\n\n Con i relativi fattori chiave da presidiare. Alert e rassegna, invece di un'analisi una tantum.\n\n\n\n\n 6", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Flusso di Lavoro Analisi Titoli", "page": 7, "text": "N OT A O PE RA TI VA — FA SI 5 -6\n\n\nAnalisi puntuale vs. monitoraggio continuo\n\n\n FAS I 1-4 FAS I 5-6\n\n Attività puntuale Presenza continuativa\n\n Richiedono una presenza continuativa nel tempo: vanno\n Possono essere svolte come attività una tantum: analisi dei casi,\n appoggiate a strumenti esterni dedicati, oppure richieste 'a\n individuazione del pattern, estensione ad altri titoli e\n chiamata' con aggiornamenti puntuali quando servono.\n mappatura dei settori.\n\n Alert di prezzo/volume su piattaforme di trading\n\n\n Alert su notizie con parole chiave settoriali\n\n\n Rassegna periodica pianificata\n\n\n\n\n 7", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Flusso di Lavoro Analisi Titoli", "page": 8, "text": "IN SIN TE SI\n\n\n\n\nUn processo ripetibile: dal pattern al monitoraggio\n\n\nSei fasi, dagli input necessari agli output attesi, per trasformare casi isolati in un sistema di analisi e\nmonitoraggio continuo dei mercati.\n\n\n\n\n 8", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Casi Concreti e Monitoraggio Mercati", "page": 1, "text": "ANALISI DI MERCATO\n\n\n\n\nCasi concreti e attività di monitoraggio per\nanticipare i mercati\n\nEsempi di performance azionarie straordinarie, i settori da presidiare e le aree da monitorare per\nintercettare i segnali prima che si traducano in movimenti di prezzo.\n\n\n\n\n 1", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Casi Concreti e Monitoraggio Mercati", "page": 2, "text": "FA SE 1 — CA SI DI PA RTE NZ A\n\n\nI casi analizzati\n\n Titolo Performance Periodo\n\n\n Arms Holdings +12.000% 5 anni\n\n\n Nvidia +575.800% 7 anni\n\n\n Tesla +27.000% 7 anni\n\n\n Apple +199.881% 10 anni\n\n\n Super Micro Computer +4.298% 2022 – 2024\n\n\n Eli Lilly +12.325% 7 anni\n\n\n Moderna +371% YTD dopo annuncio vaccino melanoma\n\n\nA seguito dell'analisi di questi esempi non esaustivi, l'obiettivo è individuare un pattern comune da ricercare su altri titoli dei mercati americani ed europei.\n 2", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Casi Concreti e Monitoraggio Mercati", "page": 3, "text": "PE RIME TRO DI RI CE RCA\n\n\nSettori in sviluppo da presidiare\n\n Biomedicale IPO, fasi di test, brevetti.\n\n\n\n\n Intelligenza artificiale (AI) IPO, aggiornamenti e rilasci di prodotto.\n\n\n\n\n Infrastrutture informatiche IPO, hardware, barriere all'ingresso, scoperte innovative.\n\n\n\n\n Energia pulita, fusione, mini nucleare,\n IPO, brevetti, autorizzazioni.\n rinnovabili\n\n\n\n\n 3", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Casi Concreti e Monitoraggio Mercati", "page": 4, "text": "SINTES I FASE 1\n\n\nProssimi passi\n\n\n 1 2 3\n\n Estendere la ricerca Monitorare in background Osservare i prezzi\n\n\n\n Seguire i corsi di Borsa dei titoli\n Seguire costantemente gli sviluppi dei\n Ricercare il pattern individuato sugli altri attenzionati per cogliere opportunità di\n settori individuati, con segnalazione\n titoli dei mercati americani ed europei. correzione (ingresso) o di rialzo\n tramite notifica delle notizie rilevanti.\n (uscita/conferma del trend).\n\n\n\n\n 4", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Casi Concreti e Monitoraggio Mercati", "page": 5, "text": "MONIT ORA GGIO CONT IN UO — DA I CA SI AN AL IZ ZAT I\n\n\nAttività per anticipare i mercati (1/2)\n\n\n Accordi commerciali e\n Ricerca scientifica e brevetti IPO e mercati primari\n commesse\n\n C O SA M O N IT O R A RE C O SA M O N IT O R A RE C O SA M O N IT O R A RE\n\n\n Nuove scoperte, depositi di brevetti,\n Calendario IPO, prospetti informativi, Partnership strategiche, contratti di fornitura,\n avanzamento di fase nei trial (ambito medico\n forchetta di valutazione, periodo di lock-up. accordi di licenza, joint venture.\n ed energetico).\n\n\n FO N T I E ST RU M EN T I FO N T I E ST RU M EN T I FO N T I E ST RU M EN T I\n\n\n Riviste scientifiche di settore, banche dati Testate finanziarie specializzate, prospetti Comunicati stampa aziendali, testate di\n brevetti, registri di sperimentazione clinica. ufficiali, banche d'affari. settore, database di operazioni M&A.\n\n SE GN A L E D A C O GL IE RE SE GN A L E D A C O GL IE RE SE GN A L E D A C O GL IE RE\n\n Passaggio a fase successiva, pubblicazione Data di quotazione fissata, revisione al rialzo Accordo con un player di riferimento,\n peer-reviewed, brevetto concesso. della forchetta di prezzo. commessa di valore significativo.\n\n\n\n 5", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Casi Concreti e Monitoraggio Mercati", "page": 6, "text": "MONIT ORA GGIO CONT IN UO — SE GNA LI COMPLE MEN TA RI\n\n\nAttività per anticipare i mercati (2/2)\n\n\n Iter regolatorio e\n Segnali dai mercati finanziari Eventi di settore e filiera\n autorizzazioni\n\n C O SA M O N IT O R A RE C O SA M O N IT O R A RE C O SA M O N IT O R A RE\n\n\n\n Approvazioni, autorizzazioni normative, Movimenti di insider, posizioni degli investitori Conferenze e keynote, capacità produttiva,\n incentivi e sussidi pubblici. istituzionali, volumi e opzioni anomale. fornitori chiave, prezzi delle materie prime.\n\n\n FO N T I E ST RU M EN T I FO N T I E ST RU M EN T I FO N T I E ST RU M EN T I\n\n\n Comunicazioni obbligatorie su transazioni Conferenze scientifiche e industriali, report di\n Enti regolatori di settore, gazzette ufficiali.\n insider/istituzionali, piattaforme di trading. filiera, dati di settore.\n\n SE GN A L E D A C O GL IE RE SE GN A L E D A C O GL IE RE SE GN A L E D A C O GL IE RE\n\n Approvazione o rigetto, nuova normativa Acquisti insider consistenti, impennata di Annuncio di dati rilevanti in conferenza,\n favorevole al settore. volumi o open interest. nuova capacità produttiva.\n\n\n\n 6", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}, {"document": "Casi Concreti e Monitoraggio Mercati", "page": 7, "text": "N OT A\n\n\n\nSei aree, un unico obiettivo: anticipare la notizia di\nmassa\n\nLe prime tre aree derivano dai casi analizzati in Fase 1; le successive tre ampliano il perimetro con segnali\ncomplementari — regolatorio, finanziario e di filiera — spesso anticipatori rispetto alla notizia di massa.\n\n\n\n\n 7", "type": "user_document", "verification": "Documento di riferimento: affermazioni non verificate esternamente"}];

